const sheetData = $json.values;
if (!sheetData || sheetData.length < 2) return [];
const headers = sheetData[0];
const results = [];
for (let i = 1; i < sheetData.length; i++) {
  const row = sheetData[i];
  if (!row || row.length === 0) continue;
  const obj = {};
  headers.forEach((header, idx) => { obj[header] = row[idx] !== undefined ? row[idx] : ''; });
  results.push({ json: obj });
}
return results;

function addBusinessDays(dateStr, days) {
  const parts = (dateStr || '').split('/');
  if (parts.length !== 3) return null;
  const [d, m, y] = parts.map(Number);
  const date = new Date(y, m - 1, d);
  let added = 0;
  while (added < days) {
    date.setDate(date.getDate() + 1);
    const dow = date.getDay();
    if (dow !== 0 && dow !== 6) added++;
  }
  return date;
}

const d = $json;
const idCaso      = d['ID Caso']       || '';
const dataAb      = d['Data Abertura'] || '';
const status      = (d['Status'] || '').toLowerCase();
const threadId    = (d['ID da thread'] || d['Thread ID'] || '').trim();
const escalado    = (d['Escalado'] || '').trim().toLowerCase();
const cliente     = d['Código Cliente'] || d['Codigo_Cliente'] || '';
const assunto     = d['Assunto']        || '';
const protoBV     = d['Protocolo BV']   || '';

// Ignora casos sem ID, sem thread, ja resolvidos ou ja escalados
if (!idCaso || !threadId) return [];
if (status === 'resolvido' || status === 'fechado' || status === 'encerrado') return [];
if (escalado === 'sim') return [];

// Calcula prazo D+2 uteis
const prazo = addBusinessDays(dataAb, 2);
if (!prazo) {
  console.log('Data invalida para', idCaso, ':', dataAb);
  return [];
}

const hoje = new Date();
hoje.setHours(0, 0, 0, 0);
prazo.setHours(0, 0, 0, 0);

// So escalona se o prazo ja venceu (prazo <= hoje)
if (prazo > hoje) {
  console.log('Prazo ainda nao venceu para', idCaso, ':', prazo.toLocaleDateString('pt-BR'));
  return [];
}

console.log('ESCALONANDO:', idCaso, '| Prazo vencido em:', prazo.toLocaleDateString('pt-BR'));

const pad = n => String(n).padStart(2, '0');
const hoje2 = new Date();
const hojeISO = hoje2.getFullYear() + '-' + pad(hoje2.getMonth() + 1) + '-' + pad(hoje2.getDate());

return [{
  json: {
    id_caso:  idCaso,
    cliente:  cliente,
    assunto:  assunto,
    proto_bv: protoBV,
    prazo_vencido: prazo.toLocaleDateString('pt-BR'),
    event_escalacao: {
      subject: '🚨 Escalar para BDO — ' + idCaso + ' | Cliente ' + cliente,
      start: { dateTime: hojeISO + 'T09:00:00', timeZone: 'America/Sao_Paulo' },
      end:   { dateTime: hojeISO + 'T09:30:00', timeZone: 'America/Sao_Paulo' },
      body: {
        contentType: 'Text',
        content: '⚠️ PRAZO VENCIDO — O caso ' + idCaso + ' ultrapassou 2 dias úteis sem resolução.\n\nCliente: ' + cliente + '\nAssunto: ' + assunto + '\nProtocolo BV: ' + protoBV + '\nPrazo original: ' + prazo.toLocaleDateString(\'pt-BR\') + '\n\nAção necessária: escalar para os líderes de atendimento (BDO).'
      },
      importance: 'high',
      isReminderOn: true,
      reminderMinutesBeforeStart: 0
    }
  }
}];
